// A day agenda from a calendar feed: the day on the left, its events on the
// right. `events` is data/icalJson's list in the frame's time zone, each
// { summary, startTime, endTime, location }: a time "YYYY-MM-DDTHH:MM:SS", an
// all-day event's date alone ("YYYY-MM-DD", its end the last day it covers).
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August',
  'September', 'October', 'November', 'December']
const BARS = ['border-sky-400', 'border-violet-400', 'border-amber-400', 'border-rose-400',
  'border-emerald-400', 'border-teal-400', 'border-orange-400', 'border-indigo-400']

const pad = (n) => String(n).padStart(2, '0')
const dayOf = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
const stampOf = (d) => `${dayOf(d)}T${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`
const dateOf = (s) => new Date(+s.slice(0, 4), +s.slice(5, 7) - 1, +s.slice(8, 10),
  +s.slice(11, 13) || 0, +s.slice(14, 16) || 0)
const allDay = (e) => e.startTime.length <= 10
const covers = (e, day) => e.startTime.slice(0, 10) <= day && e.endTime.slice(0, 10) >= day
// The bar's color follows the title, so an event keeps it from day to day.
const bar = (title) => {
  let h = 0
  for (let i = 0; i < title.length; i++) h = (h * 31 + title.charCodeAt(i)) | 0
  return BARS[Math.abs(h) % BARS.length]
}
const inMinutes = (m) => m < 60 ? `${m} min`
  : m % 60 === 0 ? `${m / 60} h` : `${Math.floor(m / 60)} h ${m % 60} min`

// The size the UI is laid out at: the image it draws into, else the frame
// as the scene sees it (app.frame is the panel's, before the turn).
const uiSize = (app, context) => {
  const turned = [90, 270].includes(app.frame.rotate)
  return [context?.imageWidth ?? (turned ? app.frame.height : app.frame.width),
    context?.imageHeight ?? (turned ? app.frame.width : app.frame.height)]
}

export function get(app, context) {
  const [, height] = uiSize(app, context)
  const now = new Date()
  const nowStamp = stampOf(now)
  const today = dayOf(now)
  const tomorrow = dayOf(new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1))
  const events = (Array.isArray(app.config.events) ? app.config.events : []).filter((e) =>
    e && typeof e.startTime === 'string' && typeof e.endTime === 'string')
  const past = (e) => !allDay(e) && e.endTime <= nowStamp
  const ongoing = (e) => !allDay(e) && e.startTime <= nowStamp && e.endTime > nowStamp

  // Today while something on it is still to come, else the next day that has
  // anything on it.
  let day = today
  if (!events.some((e) => covers(e, today) && !past(e))) {
    const ahead = events.filter((e) => !past(e) && e.endTime.slice(0, 10) >= today)
      .map((e) => (e.startTime.slice(0, 10) > today ? e.startTime.slice(0, 10) : tomorrow))
      .sort()
    if (ahead.length) day = ahead[0]
  }
  const list = events.filter((e) => covers(e, day)).sort((a, b) =>
    allDay(a) !== allDay(b) ? (allDay(a) ? -1 : 1) : a.startTime < b.startTime ? -1 : 1)

  // As many rows as fit: the ones that are over go first, then a "more" row.
  const fit = Math.max(1, Math.floor((height - 36) / 76))
  let rows = list.length > fit ? list.filter((e) => !past(e)) : list
  const more = rows.length > fit ? rows.length - fit + 1 : 0
  if (more) rows = rows.slice(0, fit - 1)

  const date = dateOf(day)
  const label = day === today ? DAYS[date.getDay()] : day === tomorrow ? 'Tomorrow' : DAYS[date.getDay()]
  const current = list.find(ongoing)
  const next = list.find((e) => !allDay(e) && e.startTime > nowStamp)
  const status = current ? `Now: ${current.summary}`
    : next && day === today ? `Next: ${next.summary} in ${inMinutes(Math.max(1,
      Math.round((dateOf(next.startTime) - now) / 60000)))}`
    : next ? `First: ${next.summary} at ${next.startTime.slice(11, 16)}`
    : list.length || !app.state.iCalURL ? '' : 'Nothing coming up'

  return (
    <div className="flex bg-stone-50 text-stone-900">
      <div className="flex flex-col justify-between w-40 sm:w-64 p-4 sm:p-8 bg-stone-900 text-stone-50">
        <div className="flex flex-col">
          <span className="text-lg sm:text-2xl uppercase text-amber-300">{label}</span>
          <span className="text-7xl sm:text-9xl font-bold leading-none">{date.getDate()}</span>
          <span className="text-xl sm:text-3xl">{MONTHS[date.getMonth()]}</span>
        </div>
        <div className="hidden sm:flex flex-col gap-1 text-stone-400">
          {list.length ? <span>{list.length === 1 ? '1 event' : `${list.length} events`}</span> : null}
          {status ? <span className="line-clamp-2">{status}</span> : null}
        </div>
      </div>
      <div className="flex-1 min-w-0 flex flex-col gap-3 p-4 sm:p-6">
        {rows.length ? null : (
          <div className="flex-1 flex items-center justify-center text-center text-xl text-stone-400 px-8">
            {app.state.iCalURL ? 'No events in the calendar' : "Add the calendar's iCal URL in the scene's settings"}
          </div>
        )}
        {rows.map((e) => (
          <div className={`flex gap-2 sm:gap-4 items-center border-l-4 ${bar(e.summary || '')} bg-white rounded-r-lg px-3 sm:px-4 py-2${past(e) ? ' opacity-50' : ''}`}>
            <div className="hidden sm:flex flex-col w-14">
              {allDay(e)
                ? <span className="text-sm font-semibold">All day</span>
                : <span className="text-lg font-semibold">{e.startTime.slice(0, 10) < day ? 'Until' : e.startTime.slice(11, 16)}</span>}
              {allDay(e) ? null : (
                <span className="text-sm text-stone-400">{e.endTime.slice(0, 10) > day ? 'later' : e.endTime.slice(11, 16)}</span>
              )}
            </div>
            <div className="flex-1 flex flex-col">
              <span className="text-base sm:text-lg font-medium truncate">{e.summary || 'Untitled'}</span>
              {e.location ? <span className="text-sm text-stone-500 truncate">{e.location}</span> : null}
            </div>
            {ongoing(e) ? (
              <span className="text-xs uppercase rounded-full bg-emerald-100 px-2 py-1 text-emerald-700">Now</span>
            ) : null}
          </div>
        ))}
        {more ? <span className="text-sm text-stone-500 px-4">{`${more} more`}</span> : null}
      </div>
    </div>
  )
}

