const EMPTY_CALENDAR = "BEGIN:VCALENDAR\nVERSION:2.0\nEND:VCALENDAR"

export function get(app) {
  const url = typeof app.config.url === "string" ? app.config.url.trim() : ""
  if (!url) return EMPTY_CALENDAR
  return frameos.fetchText(url)
}
